import symtable

def _t():

    def checkfilename(brokencode, offset):
        try:
            symtable.symtable(brokencode, 'spam', 'exec')
        except SyntaxError as e:
            assert e.filename == 'spam', ('assertEqual', e.filename, 'spam')
            assert e.lineno == 1, ('assertEqual', e.lineno, 1)
            assert e.offset == offset, ('assertEqual', e.offset, offset)
        else:
            raise AssertionError('no SyntaxError for %r' % (brokencode,))
    checkfilename('def f(x): foo)(', 14)
    checkfilename('def f(x): global x', 11)
    symtable.symtable('pass', b'spam', 'exec')
    try:
        symtable.symtable('pass', bytearray(b'spam'), 'exec')
    except TypeError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
    try:
        symtable.symtable('pass', memoryview(b'spam'), 'exec')
    except TypeError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
    try:
        symtable.symtable('pass', list(b'spam'), 'exec')
    except TypeError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

